const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const MASTERCLASS_KEY='eq_masterclass_v1';
export const MASTERCLASS_TASKS=[
 {id:'synthesis',title:'跨文本綜合摘要',skill:'整合不同觀點',target:'用 120–160 個英文字寫一份給校長的摘要，整合共同點、分歧與證據限制。不要加入文中沒有的數據。',sources:[['A · Student committee','Later library hours would help students who work after school. A survey of 80 club members found strong demand for access after 7 p.m. However, the survey did not include students who rarely use the library.'],['B · Library director','Evening staffing would require additional funding. The library can initially open late on two weekdays, then review attendance and costs after six weeks. Online resources remain available every evening.']],steps:['各用一句話概括 A 與 B 的主張。','找出雙方共同目標、證據侷限與實際取捨。','用自己的話整合；清楚標出誰提出什麼。'],criteria:['準確呈現雙方觀點與共同目標','指出調查樣本限制，未把需求當全校共識','有組織地比較，而非逐句抄寫','建議有條件且與資料連結'],model:'Both groups seek better access to learning resources, but they differ over how quickly evening provision should expand. The student committee cites demand among surveyed club members, although this sample may not represent infrequent users. The director stresses staffing costs and proposes a limited trial. A two-evening pilot could therefore test whether the expressed demand translates into sustained attendance before the school commits further funding.',focus:'這段示範展示整合方式，並非指定字數的完整交件。觀察 although 與 therefore 如何連接限制及建議。'},
 {id:'argument',title:'論證、反駁與讓步',skill:'建立有界線的主張',target:'以 180–240 個英文字回答：Should every course require group projects? 提出立場、最強反方、合理讓步與可行政策。',sources:[['Policy proposal','A department proposes requiring group projects in every course to prepare students for collaborative work.'],['Constraints','Some courses assess individual competence for professional certification. Students may have different schedules, and individual contributions can be difficult to verify. These are scenario constraints, not findings from an empirical study.']],steps:['先定義 every 與 require 的範圍。','提出最強反對意見，再說明自己接受哪些限制。','設計個人責任與例外機制，而非只喊團隊合作很重要。'],criteria:['立場清楚，避免把 every 偷換成 some','反方得到公平呈現並有實質回應','主張、理由、例子與推論能對應','使用 may／under these conditions 等適當限定'],model:'Although collaboration is an important educational goal, a universal requirement would overlook differences in what courses are designed to assess. Group work is most defensible where joint decision-making is itself an intended outcome. In courses that certify individual competence, it should complement rather than replace individual assessment. A flexible policy could require contribution logs and a short individual defence while allowing justified exceptions.',focus:'讓步不是放棄立場；它讓政策適用範圍更精確。例子與場景推論不應冒充研究事實。'},
 {id:'register',title:'同一訊息，兩種語域',skill:'依對象調整語氣',target:'將同一個延誤消息寫成兩份 80–110 字英文訊息：一封給主管的正式信、一則給熟悉同事的訊息。必須保留相同事實。',sources:[['Facts you must preserve','The draft was due on Tuesday. A data export failed. You can send the verified draft by 3 p.m. on Thursday. You can share the completed introduction today. The final review date is Friday.'],['Audience needs','The manager needs a clear impact assessment and revised commitment. Your colleague needs a friendly, practical hand-off. Neither message should blame an unnamed person or imply the Friday review has already been cancelled.']],steps:['先列出不可遺漏的五個事實。','主管信採明確主旨、責任與修正時間；同事訊息可較自然簡短。','比較兩版：資訊相同，關係距離與用語不同。'],criteria:['兩版的原因、時間與下一步一致','正式版清楚負責，沒有推卸責任','自然版友善但不含模糊承諾','沒有擅改 Friday review 的安排'],model:'Formal: I am writing to update you on the draft scheduled for Tuesday. A failed data export has delayed verification. I can provide the verified draft by 3 p.m. on Thursday and share the completed introduction today. The review remains scheduled for Friday.\n\nColleague: Quick update: the data export failed, so I need a little longer to check the draft. I can send the verified version by 3 p.m. Thursday. The introduction is ready today if that helps you get started. We are still aiming for Friday’s review.',focus:'比較 I am writing to update you 與 Quick update；兩者都把新期限說清楚。示範較短，用於觀察語氣，不是完整交件。'},
 {id:'nuance',title:'保留語氣與細微差異',skill:'精準改寫與口頭答辯',target:'以 100–140 字改寫以下意見，保留其保留態度；再對自己口頭說明 60 秒，回答「你有多確定？還需要什麼證據？」',sources:[['Original comment','The pilot seems promising, though it is hardly a definitive solution. Attendance rose, but the trial coincided with exam season. I would not rule out extending it, provided we monitor costs and reach students who did not take part.'],['Questions to consider','Does promising mean proven? Does not rule out mean fully supports? What does provided introduce? Which alternative explanation is named?']],steps:['標出 seem、hardly、would not rule out、provided。','把每個詞的語氣強度保留下來，不把審慎支持改成全面支持。','錄音功能可用裝置自己的錄音工具；本站只記錄作品文字與自評。'],criteria:['promising 未被誤寫為 conclusively successful','保留考試季這個替代解釋','保留擴大的條件與成本限制','口頭能區分已知事實、推測與仍缺證據'],model:'The writer sees potential in the pilot but stops short of calling it a settled answer. Higher attendance is encouraging, although exam-related demand may partly explain the change. Extension remains an option rather than a firm recommendation, conditional on cost monitoring and better inclusion of non-participants.',focus:'stops short of 與 remains an option 都保留原文的審慎程度；改寫不只是替換同義字。'}
];
function storage(){try{return globalThis.localStorage;}catch{return null;}}
export function readMasterclass(store=storage()){
 try{const v=JSON.parse(store?.getItem(MASTERCLASS_KEY)||'{}');return v&&typeof v==='object'&&!Array.isArray(v)?v:{};}catch{return {};}
}
export function saveMasterclass(id,text,checks,store=storage()){
 if(!MASTERCLASS_TASKS.some(t=>t.id===id)||typeof text!=='string'||!Array.isArray(checks))return false;
 try{const data=readMasterclass(store);data[id]={text:text.slice(0,12000),checks:Array.from({length:4},(_,i)=>checks[i]===true),at:new Date().toISOString()};store.setItem(MASTERCLASS_KEY,JSON.stringify(data));return true;}catch{return false;}
}
export const countEnglishWords=text=>(String(text).match(/[A-Za-z]+(?:['’\-][A-Za-z]+)*/g)||[]).length;
export function renderMasterclass(){
 const saved=readMasterclass();
 return `<article class="learning-hub home-experience masterclass"><a class="home-text-link" href="#home">← 回學習首頁</a><p class="home-label">BEYOND THE QUIZ / ADVANCED PORTFOLIO</p><h1>進階作品工坊</h1><p class="home-intro">從 B2–C1 核心練習，走向 C1–C2 的精準、整合與表達目標。</p><p class="masterclass-boundary">這是 4 個引導式作品任務，非完整 C2 課程或認證測驗。字數只是提醒；語言正確性、細膩度與口說表現，需要教師或同儕回饋。</p><p style="margin:20px 0"><a class="home-btn primary" href="#advanced">升級到 8 單元精進課程 →</a></p><ol class="home-loop-steps">${['讀懂來源與對象','獨立寫第一稿','用規準逐項檢核','隔天改寫並請人回饋'].map((x,i)=>`<li><div class="loop-icon"><span>0${i+1}</span></div><h3>${x}</h3></li>`).join('')}</ol>${MASTERCLASS_TASKS.map((t,i)=>{const draft=saved[t.id],text=typeof draft?.text==='string'?draft.text.slice(0,12000):'';return `<details class="masterclass-task" ${i===0?'open':''}><summary><span class="home-tag">任務 0${i+1}</span><strong>${t.title}</strong><small>${t.skill}</small></summary><div class="masterclass-task-body" data-masterclass-task="${t.id}"><p class="masterclass-target">${t.target}</p><div class="masterclass-sources">${t.sources.map(([title,body])=>`<section><h3>${title}</h3><p lang="en">${body}</p></section>`).join('')}</div><h3>拆成三步做</h3><ol>${t.steps.map(step=>`<li>${step}</li>`).join('')}</ol><label class="masterclass-label" for="draft-${t.id}">我的英文作品</label><textarea id="draft-${t.id}" data-masterclass-draft maxlength="12000" rows="9" placeholder="先寫自己的版本，再看示範。" lang="en">${esc(text)}</textarea><p class="masterclass-wordcount"><span data-masterclass-words>${countEnglishWords(text)}</span> 個英文詞 · 提醒用，不代表品質分數</p><fieldset><legend>我的自評 · 勾選不代表通過程度認證</legend>${t.criteria.map((c,n)=>`<label><input type="checkbox" data-masterclass-check ${draft?.checks?.[n]===true?'checked':''}>${c}</label>`).join('')}</fieldset><button class="home-btn primary" type="button" data-masterclass-save>儲存草稿與自評</button><p role="status" data-masterclass-status></p><details class="concept-recall"><summary>寫完再看：示範策略與講解</summary><p class="masterclass-model" lang="en">${t.model}</p><small>${t.focus}</small></details></div></details>`;}).join('')}<p class="home-source-note">目標編排參考 <a href="https://www.coe.int/en/web/common-european-framework-reference-languages/cefr-descriptors" target="_blank" rel="noopener noreferrer">CEFR 能力描述</a>；題材與示範由本站撰寫。草稿僅保存在此瀏覽器，納入首頁學習護照的全站備份。請先按儲存，再離開頁面。</p></article>`;
}
const bindings=new WeakMap();
export function bindMasterclass(root){
 bindings.get(root)?.abort();const controller=new AbortController();bindings.set(root,controller);
 root.addEventListener('input',e=>{if(!e.target.matches('[data-masterclass-draft]'))return;const task=e.target.closest('[data-masterclass-task]');task.querySelector('[data-masterclass-words]').textContent=countEnglishWords(e.target.value);task.querySelector('[data-masterclass-status]').textContent='有未儲存的修改。';},{signal:controller.signal});
 root.addEventListener('change',e=>{if(e.target.matches('[data-masterclass-check]'))e.target.closest('[data-masterclass-task]').querySelector('[data-masterclass-status]').textContent='自評已修改，請儲存。';},{signal:controller.signal});
 root.addEventListener('click',e=>{const button=e.target.closest('[data-masterclass-save]');if(!button)return;const task=button.closest('[data-masterclass-task]'),ok=saveMasterclass(task.dataset.masterclassTask,task.querySelector('textarea').value,[...task.querySelectorAll('[data-masterclass-check]')].map(c=>c.checked));task.querySelector('[data-masterclass-status]').textContent=ok?'✓ 已儲存於此瀏覽器，可從學習護照匯出全站備份。':'無法儲存，請先複製作品並確認瀏覽器儲存空間。';},{signal:controller.signal});
}
